    import sys
    import math

    def query(q):
        print(f"? {q}", flush=True)
        return int(sys.stdin.readline().strip())

    def estimate_divisors(gcds):
        factors = {}
        for g in gcds:
            for i in range(2, int(math.sqrt(g)) + 1):
                while g % i == 0:
                    if i in factors:
                        factors[i] += 1
                    else:
                        factors[i] = 1
                    g //= i
            if g > 1:
                if g in factors:
                    factors[g] += 1
                else:
                    factors[g] = 1
        divisors = 1
        for exp in factors.values():
            divisors *= (exp + 1)
        return divisors

    T = int(sys.stdin.readline().strip())
    for _ in range(T):
        gcds = set()
        for _ in range(22):
            q = 2 ** len(gcds)
            gcd = query(q)
            if gcd == 1:
                break
            gcds.add(gcd)
        if 1 in gcds:
            gcds.remove(1)
        if not gcds:
            print("! 2", flush=True)
            continue
        divisors = estimate_divisors(gcds)
        print(f"! {divisors}", flush=True)

main()
